$ErrorActionPreference = 'Stop'
$root = (Resolve-Path (Join-Path $PSScriptRoot '../../../..')).Path
Set-Location -LiteralPath $root
$branch = & git branch --show-current
$revision = & git rev-parse HEAD
if ($branch -cne 'codex/remote-main-20260908' -or $revision -cne '72e65cf309d700cb7d40c5b7afd53660fd39fa35') { throw 'workspace_identity_changed' }
$taskRoot = '.codex/work-items/cloud-sky-native-2026-09-22'
$outputName = if ($args.Count) { $args[0] } else { 'current-execution-state-2026-10-03.json' }
if ($outputName -notmatch '^current-execution-state-2026-10-(?:03|04)(?:-r[1-9][0-9]*)?\.json$') { throw 'checkpoint_name_invalid' }
$protected = Get-Content -LiteralPath "$taskRoot/tmp/resume-preserved-hashes-2026-10-01.json" -Raw | ConvertFrom-Json
function Bind-File([string]$relative) {
  $file = Get-Item -LiteralPath (Join-Path $root $relative)
  [ordered]@{path=$relative; bytes=$file.Length; sha256=(Get-FileHash -LiteralPath $file.FullName -Algorithm SHA256).Hash.ToLowerInvariant()}
}
$protection = @($protected | ForEach-Object {
  $bound = Bind-File $_.path
  if ($bound.sha256 -cne $_.sha256) { throw 'protected_bytes_changed' }
  $bound
})
